import sympy as S
from fractions import Fraction as F
from .authoring import maker,finish
from .common import section
q=maker('ratio-geometry',['similarity','area ratios','cevian intersections'])
P=S.Point;L=S.Line
A=P(0,0);B=P(1,0);C=P(0,1)
def cross(d,e):return L(A,d).intersection(L(B,e))[0]
p=[
q(1,r'In triangle ABC, D lies on AB and E on AC with DE parallel to BC. If AD:DB=2:3, what is [ADE]/[ABC]?',F(4,25),[(F(2,5),'Use the length ratio as the area ratio.'),(F(4,9),'Use AD/DB instead of AD/AB.'),(F(9,25),'Use the complementary side fraction.'),(F(21,25),'Report the remaining trapezoid fraction.')],[r'The parallel line gives triangle ADE similar to ABC.',r'The length scale is AD/AB=2/(2+3)=2/5.',r'Area scales by its square, giving 4/25.'],['Convert a part-to-part ratio to a part-to-whole ratio.','Both a base and its height scale in similar triangles.'],'Translate a segment ratio into an area scale.',lambda:S.Polygon(A,P(F(2,5),0),P(0,F(2,5))).area/S.Polygon(A,B,C).area,'Coordinate determinant areas.',2),
q(2,r'The medians of a triangle meet at G. What fraction of the triangle’s area is [ABG]?',F(1,3),[(F(1,2),'Use the midpoint property without accounting for the centroid.'),(F(2,3),'Use the longer centroid segment as the height fraction.'),(F(1,6),'Report one of the six smallest median triangles.'),(F(1,4),'Assume every cevian intersection is a midpoint.')],[r'The centroid lies one third of the altitude above side AB.',r'Triangles ABG and ABC share base AB, so their areas are in the ratio of their heights.',r'The ratio is 1/3; each is made of two or six equal small median triangles, respectively.'],['Use a common base to compare areas.','Relate the centroid’s altitude to the full altitude.'],'Use centroid structure through a shared-base area comparison.',lambda:S.Polygon(A,B,P(F(1,3),F(1,3))).area/S.Polygon(A,B,C).area,'Coordinate centroid and determinant area.',2),
q(3,r'In triangle ABC, AB=10, AC=15, BC=20. The internal angle bisector AD meets BC at D. Find BD.',8,[(10,'Assume an angle bisector bisects the opposite side.'),(12,'Report DC.'),(F(20,3),'Use AB/AC directly as a part-to-whole ratio.'),(5,'Use the difference of the adjacent sides.')],[r'The two subtriangles have equal angle at A, so their areas are in ratio AB:AC=2:3.',r'They also share the altitude to BC, so BD:DC=2:3.',r'Thus BD=20·2/5=8.'],['Compare the two subtriangle areas in two ways.','Convert the resulting ratio into a fraction of BC.'],'Derive and use the angle-bisector ratio.',lambda:F(20*10,10+15),'Exact area-ratio equation.',2),
q(4,r'D lies on BC with BD:DC=2:3, and E lies on CA with CE:EA=3:4. Lines AD and BE meet at P. Find AP:PD as a numerical ratio.',F(10,3),[(F(3,10),'Reverse the requested direction.'),(F(5,2),'Ignore the location of E.'),(F(7,3),'Use the whole side ratio from E alone.'),(F(10,13),'Report AP/AD instead of AP/PD.')],[r'Assign balancing masses B=3,C=2 to match BD:DC=2:3. The ratio CE:EA=3:4 then requires A=3/2.',r'The combined mass at D is 5. Along AD, the distance ratio is the inverse mass ratio, so AP:PD=5:(3/2).',r'The result is 10:3. Masses encode the same shared-altitude area equations and introduce no physical assumption.'],['Make the masses at B and C balance the point D.','Use the second side ratio to determine the mass at A.'],'Coordinate two cevian ratios through a consistent balance model.',lambda:(lambda t:t/(1-t))(cross(P(F(3,5),F(2,5)),P(0,F(4,7))).x/F(3,5)),'Independent line intersection in an affine reference triangle.'),
q(5,r'In triangle A=(0,0), B=(12,0), C=(0,9), let D be the midpoint of BC and E=(4,0). Lines AD and CE meet at P. Find AP/AD.',F(1,2),[(F(2,3),'Use the centroid ratio even though CE is not a median.'),(F(1,3),'Use AE/AB directly.'),(F(3,4),'Report CP/CE.'),(F(3,5),'Balance incompatible segment ratios.')],[r'Parameterize P on AD as (6t,9t/2). On CE it is (4s,9-9s).',r'The x-coordinates give s=3t/2. Substitution into the y-equation gives 9t/2=9-27t/2.',r'Thus t=1/2, which is AP/AD.'],['Parameterize the point on each cevian.','A line parameter gives a part-to-whole distance ratio directly.'],'Use affine parameters to resolve a non-centroid intersection.',lambda:L(P(0,0),P(6,F(9,2))).intersection(L(P(0,9),P(4,0)))[0].x/6,'Exact line intersection.'),
q(6,r'A trapezoid ABCD has parallel bases AB=6 and CD=10 and height 8. Its diagonals intersect at O. Find [AOB].',9,[(24,'Use the full height with the shorter base.'),(15,'Report a side triangle’s area.'),(25,'Report the triangle at the longer base.'),(12,'Assume the diagonal intersection is halfway up.')],[r'Triangles AOB and COD are similar with length ratio 6:10=3:5.',r'Their altitudes to the parallel bases add to 8, so the altitude of AOB is 3.',r'Therefore [AOB]=6·3/2=9.'],['Use vertical angles and the parallel bases to prove similarity.','The two heights add to the trapezoid’s height.'],'Recover a diagonal-intersection height from similarity.',lambda:abs(S.Polygon(P(0,8),P(6,8),L(P(0,8),P(10,0)).intersection(L(P(6,8),P(0,0)))[0]).area),'Coordinate diagonal intersection and area.'),
q(7,r'In triangle ABC, BD:DC=1:2 and CE:EA=1:3. If AD and BE meet at P, find [BPC]/[ABC].',F(1,10),[(F(9,10),'Use the height from A to P rather than P to BC.'),(F(1,3),'Ignore the second cevian.'),(F(1,4),'Use only the ratio on CA.'),(F(1,7),'Add segment ratios instead of balancing them.')],[r'Choose masses B=2,C=1,A=1/3. The mass at D is 3, so AP:PD=9:1.',r'Triangles PBC and ABC share base BC. Their altitude ratio is PD/AD because P lies on AD.',r'Thus the area ratio is 1/10.'],['First locate P along AD.','Compare the two triangles using the common base BC.'],'Convert a cevian-intersection ratio into an area ratio.',lambda:abs(S.Polygon(B,cross(P(F(2,3),F(1,3)),P(0,F(3,4))),C).area)/S.Polygon(A,B,C).area,'Independent determinant area after line intersection.'),
q(8,r'Triangle ABC has AB=12 and BC=18. Let h_A be its altitude to BC and h_C its altitude to AB. Find h_C/h_A.',F(3,2),[(F(2,3),'Use the side ratio in the same rather than inverse direction.'),(F(9,4),'Square an altitude ratio in a single triangle.'),(1,'Assume all altitudes are equal.'),(F(5,2),'Add bases instead of equating areas.')],[r'The same area is 18h_A/2 and 12h_C/2.',r'Equating gives 18h_A=12h_C.',r'Hence h_C/h_A=3/2. No angle or actual area is needed.'],['Write two base-height formulas for the same area.','The heights are inversely proportional to their bases.'],'Eliminate an unknown area from two altitude expressions.',lambda:F(18,12),'Two exact area expressions.',2),
q(9,r'A segment parallel to BC cuts triangle ABC into a smaller triangle ADE and a trapezoid DBCE. If the trapezoid has three times the area of ADE, find AD/AB.',F(1,2),[(F(1,3),'Use the part-to-part area ratio as a length ratio.'),(F(1,4),'Do not take the square root of the area ratio.'),(F(3,4),'Report the trapezoid’s area fraction.'),(S.sqrt(3)/2,'Use the complementary area fraction before taking a square root.')],[r'The whole triangle has four times the area of ADE.',r'The similar-triangle area ratio is therefore 1/4.',r'The positive length ratio is its square root, 1/2.'],['Convert the trapezoid comparison into a small-to-whole area ratio.','Then recover a length scale.'],'Reverse area scaling after converting part-to-whole information.',lambda:S.sqrt(S.Rational(1,4)),'Positive root of the exact area ratio.',2),
q(10,r'The altitude from the right angle of a right triangle divides its hypotenuse into lengths 9 and 16. Find the altitude.',12,[(F(25,2),'Use half the hypotenuse.'),(15,'Report the leg adjacent to the segment nine.'),(20,'Report the other leg.'),(7,'Subtract the two hypotenuse pieces.')],[r'The two small right triangles are similar, because their acute angles are complementary to the same original angles.',r'The corresponding ratios give h/9=16/h, hence h²=144.',r'The positive altitude is 12.'],['Match angles before matching sides in the two smaller triangles.','The altitude is a geometric mean of the two hypotenuse pieces.'],'Derive a geometric mean through similarity.',lambda:S.sqrt(9*16),'Coordinate check: vertices (0,0),(25,0),(9,12) form a right angle at the third point.',2),
q(11,r'A right triangle with legs 15 and 20 is divided into two smaller triangles by the altitude to its hypotenuse. What is the sum of the smaller inradii divided by the original inradius?',F(7,5),[(1,'Assume radii add under a partition.'),(F(49,25),'Use area scaling instead of length scaling.'),(F(3,5),'Include only one smaller triangle.'),(F(4,5),'Include only the other smaller triangle.')],[r'The hypotenuse is 25. Each smaller triangle is similar to the original, with length scales 15/25 and 20/25.',r'Inradii are lengths, so they scale by these same factors.',r'The ratio of their sum to the original radius is 3/5+4/5=7/5.'],['Identify the scale of each similar triangle.','A radius scales like a length, not like an area.'],'Transfer similarity to an auxiliary circle in each subtriangle.',lambda:(S.Rational(9+12-15,2)+S.Rational(12+16-20,2))/5,'Direct inradii of the two small right triangles: (9,12,15) and (12,16,20).'),
q(12,r'A trapezoid has parallel bases 8 and 12. The line through the intersection of its diagonals parallel to the bases meets the legs at E and F. Find EF.',F(48,5),[(10,'Use the midsegment although the intersection is not at half-height.'),(F(24,5),'Count only half the cross-section.'),(F(32,5),'Scale only the shorter base.'),(F(72,5),'Scale only the longer base.')],[r'The diagonal intersection is 8/(8+12)=2/5 of the full height below the shorter base.',r'Parallel cross-section lengths vary linearly from 8 to 12 with this height fraction.',r'Thus EF=8+(2/5)(12-8)=48/5. Equivalently this is 2ab/(a+b).'],['Use the similar triangles at the two bases to locate the intersection vertically.','Interpolate the full cross-section length at that height.'],'Combine diagonal similarity with linear cross-section scaling.',lambda:8+S.Rational(8,20)*(12-8),'Affine cross-section in a coordinate trapezoid.'),
q(13,r'In triangle ABC, AB=12 and AC=18. The angle bisector AD meets BC at D. A line through D parallel to AB meets AC at E. Find AE.',F(36,5),[(F(54,5),'Report CE instead of AE.'),(9,'Assume E is a midpoint.'),(12,'Copy the parallel side’s length.'),(F(72,5),'Use the wrong part-to-whole fraction.')],[r'The angle-bisector theorem gives BD:DC=2:3, so CD/CB=3/5.',r'Triangles CDE and CBA are similar, hence CE/CA=3/5.',r'Thus AE=18(1-3/5)=36/5.'],['First locate D using the angle bisector.','Then compare the small triangle at C with the whole triangle.'],'Chain angle-bisector and parallel-line ratios.',lambda:18*(1-S.Rational(18,30)),'Independent two-step affine side fraction.'),
q(14,r'D lies on AB with AD:DB=2:3 and E lies on BC with BE:EC=3:4. Line DE meets line CA at F beyond A. Find CF/FA.',2,[(F(1,2),'Invert the external segment ratio.'),(F(3,2),'Use only the ratio at D.'),(F(4,3),'Use only the ratio at E.'),(F(7,5),'Add unrelated ratio components.')],[r'Menelaus’s theorem for the transversal D,E,F gives $(AD/DB)(BE/EC)(CF/FA)=1$ using positive lengths with F external.',r'The first two factors multiply to (2/3)(3/4)=1/2.',r'Therefore CF/FA=2. The point is beyond A, consistent with CF>FA.'],['An external intersection suggests a transversal relation rather than concurrent cevians.','Keep the cyclic order of the three side ratios.'],'Use an external transversal with consistent ratio orientation.',lambda:(lambda f:f.distance(C)/f.distance(A))(L(P(F(2,5),0),P(F(4,7),F(3,7))).intersection(L(C,A))[0]),'Exact coordinate intersection gives F=(0,-1).')]
e=[
q(101,r'D is the midpoint of BC and E lies on CA with CE:EA=1:2. Lines AD and BE meet at P. Find AP/PD.',4,[(2,'Treat both lines as medians.'),(F(4,5),'Report AP/AD.'),(F(1,4),'Reverse the ratio.'),(3,'Use the whole side ratio on CA without balancing BC.')],[r'Equal masses at B and C balance D. Choose B=C=2 so that CE:EA=1:2 is balanced by A=1.',r'The total mass at D is 4. Balancing A and D places P with AP:PD=4:1.',r'This is also an area argument: equal bases on BC give equal subareas, and the ratio on CA fixes the remaining height ratio.',r'A coordinate check uses A=(0,0),B=(1,0),C=(0,1); the intersection is (2/5,2/5), four fifths of the way along AD.'],['Make the masses at B and C equal.','Choose the mass at A to satisfy the second ratio.'],'Build consistent masses and translate back to a requested distance ratio.',lambda:(lambda t:t/(1-t))(cross(P(F(1,2),F(1,2)),P(0,F(2,3))).x*2),'Independent coordinate intersection.'),
q(102,r'Two similar triangles have areas 18 and 50. Their corresponding altitudes differ by 8. Find the smaller altitude.',12,[(F(9,2),'Use the area ratio directly for the altitudes.'),(20,'Report the larger altitude.'),(8,'Use the difference as the smaller height.'),(16,'Assume the larger area doubles the height.')],[r'The area ratio is 9:25, so the positive length ratio is 3:5.',r'Write the altitudes as 3k and 5k. Their difference gives 2k=8.',r'Thus k=4 and the smaller altitude is 12.',r'Checking the two heights 12 and 20 gives squared ratio 144:400=18:50. This separates area scaling from the additive condition on lengths.'],['Take the square root of the area ratio.','Represent both altitudes using a single scale parameter.'],'Combine similarity scaling with an additive length constraint.',lambda:S.solve([S.Eq(S.Symbol('y')-S.Symbol('x'),8),S.Eq(5*S.Symbol('x'),3*S.Symbol('y'))],[S.Symbol('x'),S.Symbol('y')])[S.Symbol('x')],'Solve the two independent linear constraints.',2)]
finish('ratio-geometry','Area ratios, cevians & similarity chains','Geometry','similarity geometric-constructions',32,'398–426',
 [r'Geometry often determines a ratio long before it determines an actual length. Shared heights, parallel sides, and intersecting cevians let you move that ratio through a figure. The skill is to track exactly which two quantities are being compared.',r'Use brackets such as [ABC] for area. Before calculating a ratio, state whether the triangles share a base, share a height, or are similar. These three reasons produce different relationships.'],
 [section('Distinguish three kinds of area comparison',r'Triangles with a common altitude have area ratio equal to their base ratio. Triangles with a common base have area ratio equal to their altitude ratio. Similar triangles scale in both directions, so their area ratio is the square of their length ratio. Confusing these cases is a frequent source of plausible wrong answers.',r'A part-to-part ratio is not a part-to-whole fraction. If AD:DB=2:3, then AD/AB=2/5. Make this conversion before squaring for an area ratio or interpolating a point along a segment. When given the area of a trapezoid relative to the small triangle above it, first recover the whole triangle’s area.',r'For an angle bisector, the two adjacent subtriangles have equal included angles at the bisected vertex. The sine area formula therefore gives their area ratio as the adjacent-side ratio. Their common altitude to the opposite side converts that area ratio into the angle-bisector theorem.'),
 section('Locate intersections without guessing a centroid',r'The centroid’s two-to-one ratio applies to medians. A cevian through an arbitrary side point is not a median. For general intersections, use consistent masses, repeated area ratios, or affine coordinates. Each is a representation of the same linear balance along segments.',r'In a mass model, masses at two endpoints are inversely proportional to the distances to their balance point. Choose endpoint masses satisfying every given side ratio, then add masses at a combined point. Only after the system is consistent should you read off the desired distance ratio.',r'Coordinate parameters provide an independent check. A point written as A+t(D-A) has AP/AD=t and AP/PD=t/(1-t). The distinction between these ratios matters: a correct intersection calculation can still answer the wrong question. A point’s distance from the opposite base also changes linearly with t.'),
 section('Chain similarities and handle external points',r'Diagonals of a trapezoid create two similar triangles at the parallel bases. Their height ratio equals the base-length ratio, and their heights add to the trapezoid’s height. This locates the intersection without knowing the sloping sides. A parallel cross-section there can then be obtained by linear interpolation.',r'Lengths attached to similar figures, such as inradii, altitudes, and medians, scale by the ordinary length factor. Areas scale by its square. A partition into similar triangles can therefore make radii add to a multiple larger than the original radius even though the areas still add exactly.',r'Concurrent cevians and a collinear transversal use different ratio theorems. For an external intersection, sketch the point order and preserve the cyclic ratio orientation in Menelaus’s theorem. A positive-length formula needs the correct external configuration; a signed-coordinate calculation can verify both the ratio and the location.')],
 ['Choose the correct area-ratio justification.','Locate general cevian intersections without assuming centroid ratios.','Chain similarity through circles, heights, and external transversals.'],
 [r'Use K=bh/2 to derive common-base and common-height comparisons.',r'Scale both base and height to derive the square law for similar areas.',r'Write a cevian point as A+t(D-A) and distinguish t from t/(1-t).'],
 'A length ratio, an area ratio, and a part-to-whole fraction are different quantities. Label the numerator and denominator before simplifying.',e,p,
 dict(prompt=r'D lies on BC with BD:DC=2:1. If P lies on AD with AP:PD=3:2, find [BPC]/[ABC]. Which given ratio is unnecessary?',answer=r'The area ratio is 2/5; BD:DC is unnecessary.',steps=[r'The triangles share base BC, so compare their perpendicular heights.',r'The height fraction is PD/AD=2/(3+2). The position of D along BC does not change this.']),
 ['shared-base areas','similarity scale chains','mass balance','external transversals'],
 [(r'K_1/K_2=(\ell_1/\ell_2)^2','Similar-area scaling','converting a similarity length scale into an area ratio','The triangles or figures are similar, and the lengths correspond.'),(r'BD/DC=AB/AC','Angle-bisector ratio','locating the opposite-side intersection of an internal angle bisector','D lies on BC and AD bisects angle BAC.'),(r'AP/PD=m_D/m_A','Cevian balance','recovering an intersection ratio from consistent endpoint masses','The masses at A and D balance at P and satisfy all other side ratios.'),(r'\frac{AD}{DB}\frac{BE}{EC}\frac{CF}{FA}=1','Menelaus transversal','relating three side ratios on a line crossing a triangle','D,E,F are collinear; use the appropriate external-point configuration or signed lengths.')], 'similarity')
